!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":786,\"sizeSlug\":\"thumbnail\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-thumbnail\"><img src=\"http://localhost:8080/wp-content/uploads/2026/03/Corporate-Training-150x150.webp\" alt=\"\" class=\"wp-image-786\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":4} -->\n<h4 class=\"wp-block-heading has-text-align-center\">Corporate Training</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Corporate training often feels stiff and generic—let’s face it, it can be boring! Ninja Tropic transforms eLearning with custom graphic video animation for impactful workforce education.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"className\":\"alt\"} -->\n<div class=\"wp-block-button alt\"><a class=\"wp-block-button__link wp-element-button\">Learn more</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:acf/hubspot-form {\"name\":\"acf/hubspot-form\",\"data\":{\"title\":\"How to [gradient]Get Started[/gradient] With Expert e-Learning Consultants\",\"_title\":\"field_697ad122e258a\",\"description\":\"Ready to cure your eLearning design stress? Get in touch with one of our knowledgeable and experienced instructional design consultants and let’s talk about what you need to ensure we’re a good fit for your learning goals.\",\"_description\":\"field_697ad133e258b\",\"form\":\"\\u003cscript charset=\\u0022utf-8\\u0022 type=\\u0022text/javascript\\u0022 src=\\u0022//js.hsforms.net/forms/embed/v2.js\\u0022\\u003e\\u003cspan da