\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"className\":\"alt\"} -->\n<div class=\"wp-block-button alt\"><a class=\"wp-block-button__link wp-element-button\">Learn more</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":915,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full\"><img src=\"http://localhost:8080/wp-content/uploads/2026/03/Custom-Development-Training.webp\" alt=\"\" class=\"wp-image-915\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":4} -->\n<h4 class=\"wp-block-heading has-text-align-center\">Custom<br>Development Training</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">When learners visualize themselves in relevant scenarios, scenario-based video eLearning enhances understanding and promotes effective implementation. It’s ideal for hands-on learners!</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"className\":\"alt\"} -->\n<div class=\"wp-block-button alt\"><a class=\"wp-block-button__link wp-element-button\">Learn more</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":786,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full\"><img src=\"http://localhost:8080/wp-content/uploads/2026/03/Corporate-Training.webp\" alt=\"\" class=\"wp-image-786\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":4} -->\n<h4 class=\"wp-block-heading has-text-align-center\">Corporate Training</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Got a few minutes between meetings? Struggling to fit in mandatory training? With demanding schedules, Microlearning solutions from Ninja Tropic offer the condensed learning you need!</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"className\":\"alt\"} -->\n<div class=\"wp-block-button alt\"><a class=\"wp-block-button__link wp-element-button\">Learn more</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:spacer {\"height\":\"6rem\"} -->\n<div style=\"height:6rem\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:acf/hubspot-form {\"name\":\"acf/hubspot-form\",\"data\":{\"title\":\"Get a [gradient]FREE Consultation[/gradient] With Ninja Tropic!\",\"_title\":\"field_697ad122e258a\",\"description\":\"Are you aware of the sheer power of engaging eLearning solutions but not sure where to start? Schedule a \\u003cstrong\\u003efree 30-minute consultation\\u003c/strong\\u003e with a Ninja Tropic eLearning expert to analyze your organization’s content objectives and map out the interactive blueprint to achieve them.\",\"_description\":\"field_697ad133e258b\",\"form\":\"\\u003cscript charset=\\u0022utf-8\\u0022 type=\\u0022text/javascript\\u0022 src=\\u0022//js.hsforms.net/forms/embed/v2.js\\u0022\\u003e\\u003cspan data-mce-type=\\u0022bookmark\\u0022 style=\\u0022display: inline-block; width: 0px; overflow: hidden; line-height: 0;\\u0022 class=\\u0022mce_SELRES_start\\u0022\\u003e﻿\\u003c/span\\u003e\\u003cspan data-mce-type=\\u0022bookmark\\u0022 style=\\u0022display: inline-block; width: 0px; overflow: hidden; line-height: 0;\\u0022 class=\\u0022mce_SELRES_start\\u0022\\u003e﻿\\u003c/span\\u003e\\u003cspan 